import {readFile,writeFile} from 'node:fs/promises';
const [state,profile,note='Source avatar identity/position/frame restored; name/stat glyph shapes and edge sampling remain, other HUD/hand P2 not accepted.']=process.argv.slice(2),folder='art/review/web-v3/gameplay-seats-calibration-20261026',coverage=JSON.parse(await readFile(folder+'/coverage.json','utf8')),r=coverage.reports.find(r=>r.state===state&&r.profile===profile);
if(!r)throw Error('No current paired comparison for this state/profile');
const path=folder+'/manual-review.json',data=await readFile(path,'utf8').then(JSON.parse).catch(()=>({batch:coverage.batch,reviews:[]}));if(data.batch!==coverage.batch)throw Error('Archive prior manual review first');
data.reviews=data.reviews.filter(v=>v.state!==state||v.profile!==profile);data.reviews.push({state,profile,at:new Date().toISOString(),source:r.source,sourceSha256:r.sourceSha256,capture:r.capture,captureSha256:r.captureSha256,full:r.comparison,focused:r.focus,fullViewed:true,focusedViewed:true,note,status:'reviewed-P2-remain-not-full-page-pass'});await writeFile(path,JSON.stringify(data,null,2)+'\n');console.log({reviewed:data.reviews.length,total:coverage.reports.length});
